  // ── INDEX.HTML — Why Stocks Are Traded ──
  "index.sectionLabel5": { id: "Ekosistem", en: "Ecosystem" },
  "index.whyTradedH2": { id: "Mengapa Saham Bisa Diperjualbelikan?", en: "Why Can Stocks Be Traded?" },
  "index.whyTradedP1": { id: 'Setiap perusahaan yang sudah <a href="ipo.html">IPO</a> secara resmi membuka diri untuk publik — istilahnya: <a href="go-public.html">Go Public</a>. Artinya, laporan keuangan, jadwal <a href="rups.html">RUPS</a>, keputusan perusahaan, hingga harga saham bisa diakses semua orang.', en: 'Every company that has completed an <a href="ipo.html">IPO</a> officially opens itself to the public — the term is: <a href="go-public.html">Go Public</a>. This means financial reports, <a href="rups.html">GMS</a> schedules, corporate decisions, and stock prices are accessible to everyone.' },
  "index.analogyLabel": { id: "🏠 Analogi Properti", en: "🏠 Property Analogy" },
  "index.analogyBefore": { id: '<strong>Sebelum dijual:</strong> Lahan yang dimiliki satu perusahaan developer — tertutup, tidak bisa diperdagangkan, kita nggak tahu harganya.', en: '<strong>Before being sold:</strong> Land owned by a single developer company — closed off, cannot be traded, we don\'t know its price.' },
  "index.analogyAfter": { id: '<strong>Sesudah dijual:</strong> Lahan tersebut dibagi-bagi, setiap orang bisa membeli sesuai kemampuan. Kita bisa tahu harganya, dan bisa menjual kembali kapanpun.', en: '<strong>After being sold:</strong> The land is divided, anyone can buy as much as they can afford. We can know the price, and can resell anytime.' },
  "index.analogyStock": { id: '<strong>Begitu juga saham:</strong> Saat perusahaan go public, sahamnya bisa diperdagangkan layaknya properti — namun wajib melalui <a href="broker-saham.html">broker saham</a> di <a href="bursa-efek.html">bursa efek</a>.', en: '<strong>The same with stocks:</strong> When a company goes public, its shares can be traded like property — but must go through a <a href="broker-saham.html">stock broker</a> on the <a href="bursa-efek.html">stock exchange</a>.' },

