  // ── INDEX.HTML — 3 Pillars ──
  "index.sectionLabel7": { id: "Yang Terpenting", en: "What Matters Most" },
  "index.pillarH2": { id: "3 Pilar Keuntungan Saham", en: "3 Pillars of Stock Returns" },
  "index.pillar1h4": { id: "Saham = Bisnis", en: "Stocks = Business" },
  "index.pillar1p": { id: "Membeli saham berarti punya bisnis. Jika bisnisnya tumbuh, sahamnya pun ikut naik.", en: "Buying stocks means owning a business. If the business grows, the stock price rises too." },
  "index.pillar2h4": { id: "Capital Gain", en: "Capital Gain" },
  "index.pillar2p": { id: "Keuntungan dari selisih harga beli dan jual. Semakin besar pertumbuhan bisnis, semakin besar capital gain.", en: "Profit from the difference between buying and selling price. The bigger the business growth, the bigger the capital gain." },
